package com.example.fulfillmentservice.controller;import com.example.fulfillmentservice.model.*;import com.example.fulfillmentservice.service.FulfillmentService;import io.swagger.v3.oas.annotations.*;import io.swagger.v3.oas.annotations.tags.Tag;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/fulfillments") @Tag(name="Fulfillment")public class FulfillmentController{private final FulfillmentService service;public FulfillmentController(FulfillmentService s){service=s;}@PostMapping @Operation(summary="Start device fulfillment")public ResponseEntity<Fulfillment>create(@Valid@RequestBody CreateFulfillmentRequest q){return ResponseEntity.status(201).body(service.create(q));}@GetMapping @Operation(summary="List fulfillments or find by order")public Object list(@RequestParam(required=false)String orderId){return orderId==null?service.list():service.byOrder(orderId);}}
